('taco-bell-chipotle-chicken-quesadilla-demo', 'Chipotle chicken quesadilla', 'Taco Bell', 'Mexican', array['lunch', 'dinner']::text[], 2, 20, 'Easy', 0.9, 'Grilled flour tortilla, melted cheese and creamy chipotle sauce.', 6.49, 2.35, '[{"name": "Flour tortillas, large", "qty": 2, "unit": "", "aisle": "Bakery", "price": 3.29, "pack_qty": 8}, {"name": "Chicken thighs, boneless", "qty": 0.5, "unit": "lb", "aisle": "Meat", "price": 4.5, "pack_qty": 0}, {"name": "Monterey Jack, shredded", "qty": 1, "unit": "cup", "aisle": "Dairy", "price": 3.49, "pack_qty": 2}, {"name": "Chipotle peppers in adobo", "qty": 1, "unit": "tbsp", "aisle": "International", "price": 2.29, "pack_qty": 14}, {"name": "Sour cream", "qty": 0.25, "unit": "cup", "aisle": "Dairy", "price": 2.29, "pack_qty": 2}, {"name": "Cilantro", "qty": 2, "unit": "tbsp", "aisle": "Produce", "price": 0.99, "pack_qty": 16}, {"name": "Vegetable oil", "qty": 1, "unit": "tsp", "aisle": "Pantry", "price": 0, "pack_qty": 0}]'::jsonb, '["Season and cook the chicken in a hot skillet until charred, then chop.", "Stir minced chipotle and a spoon of adobo into the sour cream.", "Fill tortillas with cheese, chicken, cilantro and a swipe of sauce; fold.", "Toast in a dry pan 2 to 3 minutes per side until the cheese melts."]'::jsonb),
('chilis-chicken-enchilada-soup-demo', 'Chicken enchilada soup', 'Chili''s', 'Mexican', array['lunch', 'dinner']::text[], 4, 40, 'Easy', 0.9, 'Thick, cheesy tortilla soup topped with crispy strips.', 7.29, 2.1, '[{"name": "Chicken thighs, boneless", "qty": 1, "unit": "lb", "aisle": "Meat", "price": 6.5, "pack_qty": 0}, {"name": "Chipotle peppers in adobo", "qty": 1, "unit": "tbsp", "aisle": "International", "price": 2.29, "pack_qty": 14}, {"name": "Frozen corn", "qty": 1, "unit": "cup", "aisle": "Frozen", "price": 1.99, "pack_qty": 3}, {"name": "Black beans", "qty": 1, "unit": "can", "aisle": "Pantry", "price": 1.19, "pack_qty": 1}, {"name": "Monterey Jack, shredded", "qty": 1, "unit": "cup", "aisle": "Dairy", "price": 3.49, "pack_qty": 2}, {"name": "Masa harina", "qty": 3, "unit": "tbsp", "aisle": "International", "price": 3.99, "pack_qty": 64}, {"name": "Chicken broth", "qty": 4, "unit": "cup", "aisle": "Pantry", "price": 2.49, "pack_qty": 4}, {"name": "Limes", "qty": 1, "unit": "", "aisle": "Produce", "price": 0.35, "pack_qty": 1}]'::jsonb, '["Brown the chicken in a pot, then remove and shred.", "Whisk masa into the broth and simmer with chipotle until thick.", "Add corn, beans and chicken; simmer 10 minutes.", "Stir in cheese off the heat and finish with lime."]'::jsonb),
('chick-fil-a-spicy-southwest-salad-demo', 'Spicy southwest salad', 'Chick-fil-A', 'American', array['lunch']::text[], 2, 25, 'Easy', 0.9, 'Romaine, spicy grilled chicken, corn and black bean salsa, cheese and chili-lime dressing.', 10.99, 3.6, '[{"name": "Romaine hearts", "qty": 1, "unit": "", "aisle": "Produce", "price": 3.49, "pack_qty": 3}, {"name": "Chicken thighs, boneless", "qty": 0.5, "unit": "lb", "aisle": "Meat", "price": 4.5, "pack_qty": 0}, {"name": "Frozen corn", "qty": 0.5, "unit": "cup", "aisle": "Frozen", "price": 1.99, "pack_qty": 3}, {"name": "Black beans", "qty": 0.5, "unit": "can", "aisle": "Pantry", "price": 1.19, "pack_qty": 1}, {"name": "Monterey Jack, shredded", "qty": 0.5, "unit": "cup", "aisle": "Dairy", "price": 3.49, "pack_qty": 2}, {"name": "Sour cream", "qty": 0.25, "unit": "cup", "aisle": "Dairy", "price": 2.29, "pack_qty": 2}, {"name": "Limes", "qty": 1, "unit": "", "aisle": "Produce", "price": 0.35, "pack_qty": 1}, {"name": "Chili powder", "qty": 1, "unit": "tsp", "aisle": "Pantry", "price": 0, "pack_qty": 0}]'::jsonb, '["Rub chicken with chili powder and salt; grill and slice.", "Char the corn in a dry skillet and toss with rinsed beans.", "Whisk sour cream, lime juice and a pinch of chili powder for the dressing.", "Pile romaine with chicken, corn salsa and cheese; drizzle dressing."]'::jsonb),
('olive-garden-fettuccine-alfredo-demo', 'Fettuccine Alfredo', 'Olive Garden', 'Italian', array['dinner']::text[], 2, 20, 'Easy', 0.9, 'Wide noodles in a glossy butter, cream and parmesan sauce.', 17.29, 2.9, '[{"name": "Fettuccine", "qty": 8, "unit": "oz", "aisle": "Pantry", "price": 1.79, "pack_qty": 16}, {"name": "Heavy cream", "qty": 1, "unit": "cup", "aisle": "Dairy", "price": 4.29, "pack_qty": 2}, {"name": "Butter", "qty": 3, "unit": "tbsp", "aisle": "Dairy", "price": 4.99, "pack_qty": 16}, {"name": "Parmesan, grated", "qty": 0.75, "unit": "cup", "aisle": "Dairy", "price": 4.99, "pack_qty": 1.5}, {"name": "Garlic cloves", "qty": 2, "unit": "", "aisle": "Produce", "price": 0.6, "pack_qty": 10}]'::jsonb, '["Boil the fettuccine in well-salted water.", "Melt butter with garlic, add cream and simmer 3 minutes.", "Whisk in parmesan off the heat until smooth.", "Toss with pasta and a splash of pasta water."]'::jsonb),
('panera-creamy-tomato-soup-demo', 'Creamy tomato soup', 'Panera Bread', 'American', array['lunch']::text[], 4, 30, 'Easy', 0.9, 'Smooth tomato soup finished with cream and basil.', 7.59, 1.7, '[{"name": "Crushed tomatoes", "qty": 28, "unit": "oz", "aisle": "Pantry", "price": 2.29, "pack_qty": 28}, {"name": "Tomato paste", "qty": 2, "unit": "tbsp", "aisle": "Pantry", "price": 1.19, "pack_qty": 6}, {"name": "Heavy cream", "qty": 0.5, "unit": "cup", "aisle": "Dairy", "price": 4.29, "pack_qty": 2}, {"name": "Shallot", "qty": 1, "unit": "", "aisle": "Produce", "price": 0.99, "pack_qty": 3}, {"name": "Fresh basil", "qty": 0.25, "unit": "cup", "aisle": "Produce", "price": 2.99, "pack_qty": 1}, {"name": "Butter", "qty": 2, "unit": "tbsp", "aisle": "Dairy", "price": 4.99, "pack_qty": 16}, {"name": "Chicken broth", "qty": 2, "unit": "cup", "aisle": "Pantry", "price": 2.49, "pack_qty": 4}]'::jsonb, '["Soften shallot in butter, then cook the tomato paste until brick red.", "Add tomatoes and broth; simmer 15 minutes.", "Blend smooth, then stir in cream and torn basil."]'::jsonb),
('california-pizza-kitchen-margherita-flatbread-demo', 'Margherita flatbread', 'California Pizza Kitchen', 'Italian', array['lunch', 'snack']::text[], 2, 20, 'Easy', 0.9, 'Thin crust with tomato, fresh mozzarella, parmesan and basil.', 13.99, 3.1, '[{"name": "Naan or flatbread", "qty": 2, "unit": "", "aisle": "Bakery", "price": 3.49, "pack_qty": 4}, {"name": "Fresh mozzarella", "qty": 4, "unit": "oz", "aisle": "Dairy", "price": 4.49, "pack_qty": 8}, {"name": "Tomato paste", "qty": 2, "unit": "tbsp", "aisle": "Pantry", "price": 1.19, "pack_qty": 6}, {"name": "Parmesan, grated", "qty": 2, "unit": "tbsp", "aisle": "Dairy", "price": 4.99, "pack_qty": 24}, {"name": "Fresh basil", "qty": 0.25, "unit": "cup", "aisle": "Produce", "price": 2.99, "pack_qty": 1}, {"name": "Garlic cloves", "qty": 1, "unit": "", "aisle": "Produce", "price": 0.6, "pack_qty": 10}]'::jsonb, '["Heat the oven to 475\u00b0F.", "Thin tomato paste with water, garlic and salt; spread on the flatbreads.", "Top with torn mozzarella and parmesan; bake 8 to 10 minutes.", "Finish with fresh basil."]'::jsonb)
